## Why This Is Asked

This question tests practical string data structure knowledge for autocomplete systems. It's beginner-friendly but reveals depth in memory management and edge case handling.

## Key Concepts

- **Trie with dual counters**: Each node tracks pass and end counts to handle duplicate words correctly
- **Time complexity**: O(length) for all operations
- **Memory optimization**: Pruning unused nodes saves space
- **Pass count**: Number of words that pass through the node
- **End count**: Number of words that end at the node

## Code Example

```python
class TrieNode:
    def __init__(self):
        self.children = {}
        self.pass_count = 0
        self.end_count = 0

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insertWord(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
            node.pass_count += 1
        node.end_count += 1

    def deleteWord(self, word):
        node = self.root
        path = [node]
        for char in word:
            if char not in node.children:
                return
            node = node.children[char]
            path.append(node)
        if node.end_count > 0:
            node.end_count -= 1
        for node in path:
            node.pass_count -= 1

    def countWordsWithPrefix(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return 0
            node = node.children[char]
        return node.pass_count
```

## Why This Is Asked
Streaming data often requires maintaining a running statistic under insertions and deletions. The median is robust and a common interview target for dynamic data structures.

## Key Concepts
- Two-heap approach: keep lower half in a max-heap and upper half in a min-heap.
- Duplicates supported; lazy deletion via a delay map.
- Rebalancing invariant: size difference at most 1; median derived from heap tops.

## Code Example
```javascript
class MedianDS {
  constructor(){
    this.lo = new MaxHeap(); // lower half
    this.hi = new MinHeap(); // upper half
    this.delayed = new Map();
    this.sizeLo = 0;
    this.sizeHi = 0;
  }
  _cleanTop(h) {
    const top = h.peek();
    while (top !== null && this.delayed.get(top) > 0) {
      h.pop();
      this.delayed.set(top, this.delayed.get(top) - 1);
    }
  }
  add(x){
    if (this.sizeLo === 0 || x <= this.lo.peek()) {
      this.lo.push(x); this.sizeLo++;
    } else { this.hi.push(x); this.sizeHi++; }
    this._balance();
  }
  remove(x){
    const loTop = this.lo.peek();
    if (loTop !== null && x <= loTop) {
      this.delayed.set(x, (this.delayed.get(x) || 0) + 1);
      this.sizeLo--;
      if (x === loTop) this._cleanTop(this.lo);
    } else {
      this.delayed.set(x, (this.delayed.get(x) || 0) + 1);
      this.sizeHi--;
      this._cleanTop(this.hi);
    }
    this._balance();
  }
  _balance(){
    if (this.sizeLo > this.sizeHi + 1) {
      this.hi.push(this.lo.pop()); this.sizeLo--; this.sizeHi++;
    } else if (this.sizeHi > this.sizeLo) {
      this.lo.push(this.hi.pop()); this.sizeHi--; this.sizeLo++;
    }
    this._cleanTop(this.lo); this._cleanTop(this.hi);
  }
  getMedian(){
    if (this.sizeLo === 0) return null;
    if (this.sizeLo > this.sizeHi) return this.lo.peek();
    return (this.lo.peek() + this.hi.peek()) / 2;
  }
}
```

## Why This Is Asked
Maintains real-time median in O(log n) per op with duplicates, a common interview pattern.

## Key Concepts
- Median maintenance with two heaps
- Lazy deletion for erase
- Size-balance invariants and edge cases
- Handling empty state

## Code Example
```javascript
class MedianMultiset {
  constructor(){ this.lower = new MaxHeap(); this.upper = new MinHeap(); this.delayed = new Map(); this.size = 0; }
  _pruneLower(){ while(!this.lower.isEmpty() && (this.delayed.get(this.lower.peek())||0)>0){ const v=this.lower.pop(); this.delayed.set(v,(this.delayed.get(v)||0)-1); } }
  _pruneUpper(){ while(!this.upper.isEmpty() && (this.delayed.get(this.upper.peek())||0)>0){ const v=this.upper.pop(); this.delayed.set(v,(this.delayed.get(v)||0)-1); } }
  _balance(){ if(this.lower.size>this.upper.size+1) this.upper.push(this.lower.pop()); else if(this.upper.size>this.lower.size) this.lower.push(this.upper.pop()); }
  insert(v){ if(this.lower.isEmpty()||v<=this.lower.peek()) this.lower.push(v); else this.upper.push(v); this.size++; this._balance(); }
  erase(v){ if(this.size===0) return; this.delayed.set(v,(this.delayed.get(v)||0)+1); this.size--; if(v<=this.lower.peek()) this._pruneLower(); else this._pruneUpper(); this._balance(); }
  getMedian(){ if(this.size===0) return null; this._pruneLower(); this._pruneUpper(); if(this.size%2===1) return this.lower.peek(); return (this.lower.peek()+this.upper.peek())/2; }
}
```

